import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create material with texture
  const material = new MeshBasicNodeMaterial();

  // Load and apply texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    material.colorNode = texture(tex, uv());
    material.needsUpdate = true;
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    mesh.position.set(config.scenePosition[0], config.scenePosition[1], config.scenePosition[2]);
  }
  if (config.sceneRotation) {
    mesh.rotation.set(config.sceneRotation[0], config.sceneRotation[1], config.sceneRotation[2]);
  }
  if (config.sceneScale) {
    mesh.scale.set(config.sceneScale[0], config.sceneScale[1], config.sceneScale[2]);
  }

  // Create text overlay
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const group = new THREE.Group();
  group.add(mesh);

  if (textItems.length > 0) {
    const item = textItems[0];
    const fontSize = item.typography?.fontSize ?? 39;
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize / 100, // Convert px to scene units (approximate)
      color: '#e8ecf2',
      align: 'left'
    });
    textMesh.position.set(-0.45, 0.35, 0.01);
    group.add(textMesh);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
